  id="generic-types-an-example-typer-definition-1"
  bind:intersecting={visibleById["generic-types-an-example-typer-definition-1"]}
  onIntersectChange={(visible) => setVisible("generic-types-an-example-typer-definition-1", visible)}
>Generic Types: an Example Typer Definition</SectionComponent>
